struct vector4d {
  float x, y, z, w;
} __attribute__((aligned(16)));

struct frame_info {
  float age;
  int ifl_frame_boost;
  int ifl_frame_locked;
};

struct vector3d {
  float x, y, z;
};

struct instance_render_info {
  float number_of_faces_to_attempt;
  vector4d local_to_world[4];
  unsigned int force_flags;
  unsigned int color_scale;
  float camera_relative_rotation;
  frame_info frame_time_info;
  void *my_region;
  float particle_scale;
  void *my_light_set;
  void *alt_materials;
  int frame;
  vector3d render_scale;

  bool operator<(const instance_render_info& iri) const { return frame < iri.frame; }
} __attribute__((aligned(16)));

extern "C" void push_heap(instance_render_info *, int, int,
                          instance_render_info)
  __asm__("__push_heap__H3ZP20instance_render_infoZiZ20instance_render_info_X01X11X11X21_v");

void push_heap(instance_render_info* first, int holeIndex, int topIndex,
               instance_render_info value) {
  int parent = (holeIndex - 1) / 2;
  while (holeIndex > topIndex && *(first + parent) < value) {
    *(first + holeIndex) = *(first + parent);
    holeIndex = parent;
    parent = (holeIndex - 1) / 2;
  }
  *(first + holeIndex) = value;
}
